export async function getComments(slug, { signal } = {}) {
  const res = await fetch(`/api/articles/${slug}/comments`, { signal });
  if (!res.ok) {
    let detail = "";

    try {
      const body = await res.json();
      if (body?.error) {
        detail = ` (${body.error})`;
      }
    } catch {
      // Keep the generic status message when the error body is not JSON.
    }

    throw new Error(`Failed to load comments: ${res.status}${detail}`);
  }

  const data = await res.json();
  return Array.isArray(data.comments) ? data.comments : [];
}

